let e=require("electron");var t={};for(let e of process.argv)if(e.startsWith(`--isis-code=`))t.code=e.slice(12);else if(e.startsWith(`--isis-pin=`))t.pin=e.slice(11);else if(e===`--isis-input-test`)t.inputTest=!0;else if(e===`--isis-clipboard-test`)t.clipboardTest=!0;else if(e===`--isis-audio-only`)t.audioOnly=!0;else if(e.startsWith(`--isis-autostop=`)){let n=Number(e.slice(16));Number.isFinite(n)&&n>0&&(t.autostop=n)}else if(e.startsWith(`--isis-pair=`)){let n=e.slice(12),[r,i]=n.includes(`,`)?n.split(`,`):[n,``];r&&i&&(t.pair={id:r,secret:i})}e.contextBridge.exposeInMainWorld(`isis`,{...t,readClipboard:()=>e.ipcRenderer.invoke(`isis:clipboard-read`),writeClipboard:t=>e.ipcRenderer.invoke(`isis:clipboard-write`,t),setFullscreen:t=>{e.ipcRenderer.send(`isis:set-fullscreen`,t)},getPairs:()=>e.ipcRenderer.invoke(`isis:pairs-get`),savePair:t=>e.ipcRenderer.invoke(`isis:pairs-save`,t),removePair:t=>e.ipcRenderer.invoke(`isis:pairs-remove`,t)});